import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  onChange?: (value: Date | null) => void;
};

type QuickOption = {
  value: string;
  label: string;
  date: Date;
};

function startOfDay(source: Date): Date {
  const result = new Date(source);
  result.setHours(0, 0, 0, 0);
  return result;
}

function subtractDays(source: Date, days: number): Date {
  const result = startOfDay(source);
  result.setDate(result.getDate() - days);
  return result;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return (
    a !== null &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date | null>(null);

  const today = startOfDay(new Date());
  const quickOptions: QuickOption[] = [
    { value: 'today', label: 'Сегодня', date: today },
    { value: 'yesterday', label: 'Вчера', date: subtractDays(today, 1) },
    { value: 'week-ago', label: 'Неделя назад', date: subtractDays(today, 7) },
  ];

  const selectDate = (date: Date) => {
    setSelected(date);
    onChange?.(date);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.value}
            active={isSameDay(selected, option.date)}
            onClick={() => selectDate(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar
        locale="ru-RU"
        value={selected}
        onValueChange={(nextValue) => {
          setSelected(nextValue);
          onChange?.(nextValue);
        }}
      />
    </div>
  );
}

